// @Controller with @ResponseBody — returns JSON from specific method
@Controller
public class MixedController {
    @GetMapping("/page")         // returns HTML view
    public String showPage() { return "page"; }

    @GetMapping("/api/data")
    @ResponseBody               // THIS method returns JSON
    public Data getData() { return new Data(); }
}

// @RestController — @ResponseBody implicit on ALL methods
@RestController
public class ApiController {
    @GetMapping("/data")        // automatically returns JSON
    public Data getData() { return new Data(); }
}
```

