// Entity — DB-mapped, has all fields including internal ones
@Entity
public class User {
    @Id Long id;
    String name, email;
    String passwordHash; // should NEVER appear in API response!
    @OneToMany List<Order> orders; // lazy — causes serialization issue
}

// DTO — only what the API should expose
public class UserResponse {
    Long id;
    String name;
    String email;
    // No password, no orders — clean and safe
